const fresh=()=>({level:1,xp:0,yen:0,runYen:0,wins:0,lifetimeWins:0,lifetimeYen:0,rebirths:0,lifetimeRebirths:0,prestiges:0,claimed:[],trait:null,style:null,techniques:[],techniqueSlots:1,equippedTechniques:[],moveOrder:["punch","flee","block","cursed-energy-punch"],district:"tokyo",gear:{weapons:[],accessories:[]},stats:{energy:10,defense:10,melee:10},statPoints:0,story:0,raidCooldowns:{},drops:[],admin:false,settings:{language:"en",color:"#0d0c12"}});
const SAVE_KEY="cursed-grind-save-v3",OLD_SAVE_KEY="cursed-grind-save-v2";let state;
try{const currentSave=localStorage.getItem(SAVE_KEY),saved=JSON.parse(currentSave||localStorage.getItem(OLD_SAVE_KEY)||"{}");state=Object.assign(fresh(),saved);if(!currentSave&&saved.technique?.name)state.techniques=[Object.assign({id:"legacy",damage:1.6,level:1,xp:0},saved.technique)];state.settings=Object.assign(fresh().settings,state.settings||{});state.gear=Object.assign(fresh().gear,state.gear||{});state.stats=Object.assign(fresh().stats,state.stats||{});if(!Array.isArray(state.techniques))state.techniques=[];if(!Array.isArray(state.moveOrder))state.moveOrder=fresh().moveOrder.slice();if(!Array.isArray(state.equippedTechniques))state.equippedTechniques=state.techniques.slice(0,state.techniqueSlots||1).map(t=>t.id);state.moveOrder=state.moveOrder.map(id=>{if(!id.startsWith("tech-"))return id;const t=state.techniques.find(x=>id==="tech-"+x.id);if(!t)return id;const first=(t.moves||TECHNIQUES.find(x=>x.id===t.id)?.moves||[{id:"strike"}])[0];return "tech-"+t.id+"-"+first.id;});}catch{state=fresh();}
let enemyHp=0,enemyMax=0,playerHp=100,playerMax=100,blockNext=false,battle=null,arenaSocket=null,arenaMatch=null,arenaQueued=false,toastTimer,activeBattleMode="pve";
const $=id=>document.getElementById(id),tr=key=>(TEXT[state.settings.language]||TEXT.en)[key]||TEXT.en[key]||key;
const fmt=n=>Math.floor(n).toLocaleString(state.settings.language==="ja"?"ja-JP":"en-US"),xpNeed=l=>Math.floor(100*Math.pow(l,1.48));
const local=(item,key)=>state.settings.language==="ja"&&item[key+"Ja"]?item[key+"Ja"]:state.settings.language==="ja"&&key==="name"&&item.ja?item.ja:item[key];
const currentDistrict=()=>DISTRICTS.find(d=>d.id===state.district)||DISTRICTS[0],rebirthNeed=()=>25+state.rebirths*5;
const rebirthBoost=()=>1+state.rebirths*.1,prestigeBoost=()=>1+state.prestiges*.25;
const damageMultiplier=()=>1+(state.trait?.bonus||0)+(state.style?.bonus||0);
const combatPower=()=>Math.max(2,Math.floor((state.level*2+4)*rebirthBoost()*prestigeBoost()*damageMultiplier()));
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state));}
function notify(text){const el=$("toast");el.textContent=text;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),2200);}
function applySettings(){document.documentElement.style.setProperty("--bg",state.settings.color||"#0d0c12");$("color-setting").value=state.settings.color||"#0d0c12";$("language-setting").value=state.settings.language||"en";document.documentElement.lang=state.settings.language||"en";document.querySelectorAll("[data-t]").forEach(el=>{const key=el.dataset.t,txt=tr(key);const icon=el.querySelector("b");if(icon)icon.textContent="↗";else el.textContent=txt;});}
function rankName(){return state.settings.language==="ja"?(state.level>=50?"特級":state.level>=25?"1級":state.level>=10?"2級":"4級"):(state.level>=50?"Special Grade":state.level>=25?"Grade 1":state.level>=10?"Grade 2":"Grade 4");}
function rankIndex(){return state.level>=50?3:state.level>=25?2:state.level>=10?1:0;}
function addXp(amount){state.xp+=Math.floor(amount);let gained=0;while(state.xp>=xpNeed(state.level)){state.xp-=xpNeed(state.level);state.level++;gained++;}if(gained){state.statPoints=(state.statPoints||0)+gained*3;notify("LEVEL UP · "+state.level+" · +"+(gained*3)+" stat points");}}
function addYen(amount){const gain=Math.floor(amount*prestigeBoost());state.yen+=gain;state.runYen+=gain;state.lifetimeYen+=gain;}
function moveCatalog(){const list=MOVE_BASE.slice();for(const w of state.gear.weapons||[])if(w.equipped)list.push({id:'weapon-'+w.name.toLowerCase().replaceAll(' ','-'),name:w.name.includes('Spear')?'Piercing Thrust':'Weapon Strike',type:'weapon',desc:w.name+' · weapon technique'});if(state.level>=10)list.push({id:"basic-rct",name:"Basic RCT",type:"heal",desc:"Restore a small amount of health with reverse cursed technique."});if(state.level>=25)list.push({id:"normal-rct",name:"Normal RCT",type:"heal",desc:"A more effective reverse cursed technique."});if(state.level>=50)list.push({id:"advanced-rct",name:"Advanced RCT",type:"heal",desc:"Advanced reverse cursed technique restores substantial health."});for(const t of state.techniques){const moves=t.moves||TECHNIQUES.find(x=>x.id===t.id)?.moves||[{id:"strike",name:t.name+" · Strike",damage:t.damage,desc:"Technique attack."}];for(const m of moves)list.push({id:"tech-"+t.id+"-"+m.id,name:m.name,type:"technique",damage:m.damage,desc:t.rarity.toUpperCase()+" · Lv. "+t.level+" · "+m.desc,technique:t,locked:!state.equippedTechniques.includes(t.id)});}return list;}
function syncGradeMoves(){const available=new Set(moveCatalog().map(m=>m.id));for(const id of available)if(["basic-rct","normal-rct","advanced-rct"].includes(id)&&!state.moveOrder.includes(id)&&state.moveOrder.length<8)state.moveOrder.push(id);}
function missionValue(m){return m.kind==="wins"?state.wins:m.kind==="level"?state.level:m.kind==="yen"?state.runYen:0;}
function renderMissions(){$("mission-list").innerHTML=MISSIONS.map(m=>{const done=state.claimed.includes(m.id),value=Math.min(missionValue(m),m.goal),complete=value>=m.goal;return '<article class="panel mission-card '+(done?"completed":complete?"complete":"")+'"><div><span class="section-index">REWARD</span><h3>'+m.title+'</h3><p>'+m.desc+'</p></div><span class="reward">+'+fmt(m.xp)+' XP<br>+'+fmt(m.yen)+' ¥</span><div class="mission-progress"><div class="xp-track"><i style="width:'+Math.floor(value/m.goal*100)+'%"></i></div><small>'+fmt(value)+' / '+fmt(m.goal)+'</small></div>'+(done?'<button class="secondary claim" disabled>'+tr("complete")+'</button>':complete?'<button class="primary claim" data-claim="'+m.id+'">'+tr("claim")+'</button>':'')+'</article>';}).join("");}
function renderDistricts(){$("district-list").innerHTML=DISTRICTS.map(d=>{const locked=state.level<d.level,selected=d.id===state.district;return '<button class="district '+(locked?"locked ":"")+(selected?"selected":"")+'" data-district="'+d.id+'" '+(locked?"disabled":"")+'><span><strong>'+(state.settings.language==="ja"?d.ja:d.name)+'</strong><small>LV '+d.level+'+ · '+fmt(d.xp)+' XP / '+fmt(d.yen)+' ¥</small></span><em>'+(locked?tr("locked"):selected?"ACTIVE":"SELECT")+'</em></button>';}).join("");}
function renderInventory(){syncGradeMoves();const catalog=moveCatalog();const equipped=state.moveOrder;$("move-count").textContent=equipped.length+" / "+(state.moveSlots||8)+" EQUIPPED";$("inventory-list").innerHTML=catalog.map(m=>{const index=equipped.indexOf(m.id),isEquipped=index>=0,levelText=m.technique?'<span class="move-level">LEVEL '+m.technique.level+' · '+m.technique.xp+'/'+(m.technique.level*100)+' XP</span>':'';return '<article class="inventory-move '+(isEquipped?"equipped":"")+'"><span class="move-order">'+(isEquipped?String(index+1).padStart(2,"0"):"—")+'</span><div class="move-info"><b>'+m.name+'</b><small>'+m.desc+'</small>'+levelText+'</div><div class="move-controls">'+(isEquipped?'<button data-order="up" data-id="'+m.id+'" '+(index===0?"disabled":"")+' aria-label="Move up">↑</button><button data-order="down" data-id="'+m.id+'" '+(index===equipped.length-1?"disabled":"")+' aria-label="Move down">↓</button><button class="equip-button" data-equip="'+m.id+'">UNEQUIP</button>':'<button class="equip-button" data-equip="'+m.id+'" '+(equipped.length>=(state.moveSlots||8)||m.locked?"disabled":"")+'>EQUIP</button>')+'</div></article>';}).join("");}
function renderBattle(){const d=currentDistrict();$("zone-name").textContent=state.settings.language==="ja"?d.ja:d.name;$("enemy-grade").textContent=(d.level>=50?"SPECIAL GRADE":d.level>=25?"GRADE 1":d.level>=10?"GRADE 2":"GRADE 4")+" CURSE";$("enemy-name").textContent=d.enemy;$("enemy-glyph").textContent=d.glyph;$("battle-power").textContent=fmt(combatPower());$("battle-reward").textContent="+"+fmt(d.xp)+" XP · +"+fmt(d.yen*prestigeBoost())+" ¥";$("battle-kills").textContent=fmt(state.wins);$("battle-state").classList.toggle("running",!!battle);$("battle-state").querySelector("span").textContent=battle?"YOUR TURN":"IDLE";$("start-battle").disabled=!!battle;$("start-battle").textContent=battle?"BATTLE IN PROGRESS":"START BATTLE";$("hp-fill").style.width=(enemyMax?Math.max(0,enemyHp/enemyMax*100):0)+"%";$("hp-label").textContent="Enemy HP · "+fmt(Math.max(0,enemyHp))+" / "+fmt(enemyMax);$("player-hp-fill").style.width=(playerMax?Math.max(0,playerHp/playerMax*100):0)+"%";$("player-hp-label").textContent=fmt(Math.max(0,playerHp))+" / "+fmt(playerMax);$("battle-actions").innerHTML=moveCatalog().filter(m=>state.moveOrder.includes(m.id)).map(m=>'<button class="action-button" data-action="'+m.id+'" '+(!battle?"disabled":"")+'><b>'+m.name+'</b><small>'+m.desc+'</small></button>').join("");$("turn-label").textContent=battle?(battle.playerTurn?"Your turn. Choose a move.":"The curse is preparing to strike."):"Choose a district and start a battle.";}
function renderGacha(){const style=state.style?state.style.name+" · "+state.style.rarity.toUpperCase():"Untrained";$("style-current").textContent="Current: "+style;$("trait-current").textContent="Current: "+(state.trait?state.trait.name+" · "+state.trait.rarity.toUpperCase():tr("unawakened"));$("technique-roll-status").textContent=state.techniques.length+" techniques learned";}
function renderExtra(){
 const bosses=[['Gojo Satoru',120000],['Ryomen Sukuna',220000],['Toji Fushiguro',90000],['Mahito',65000]];
 $('boss-list').innerHTML=bosses.map((b,i)=>`<button class="district" data-boss="${i}"><span><strong>${b[0]}</strong><small>Canon boss · unique drops</small></span><em>FIGHT</em></button>`).join('');
 $('story-list').innerHTML=[['First Day at Jujutsu High',4],['Cursed Womb',4],['Junpei Yoshino',3],['Kyoto Goodwill Event',2],['Shibuya Incident',1],['Culling Game',0]].map(([name,grade],n)=>`<article class="panel mission-card"><div><span class="section-index">${grade?'GRADE '+grade:'SPECIAL GRADE'}</span><h3>${name}</h3><p>Chapter ${n+1} · follow Yuji’s story</p></div><span class="reward">${state.story>n?'CLEARED':state.level>=(n<2?1:n<4?10:25)?'AVAILABLE':'LOCKED'}</span>${state.story===n&&state.level>=(n<2?1:n<4?10:25)?`<button class="primary story-clear" data-story="${n}">COMPLETE CHAPTER</button>`:''}</article>`).join('');
 $('awakening-list').innerHTML=state.techniques.map(t=>`<article class="panel mission-card"><div><span class="section-index">${t.level>=1000?'AWAKENING READY':'LEVEL '+t.level+' / 1000'}</span><h3>${t.name}${t.awakened?' · Awakened':''}</h3><p>${t.xp} / ${Math.min(t.level,1000)*100} XP</p></div><button class="primary awaken" data-awaken="${t.id}" ${t.level<1000||t.awakened?'disabled':''}>${t.awakened?'AWAKENED':'AWAKEN'}</button></article>`).join('')||'<article class="panel mission-card">Learn a technique to begin awakening it.</article>';
 const gear=[...state.gear.weapons.map(x=>({...x,kind:'weapons'})),...state.gear.accessories.map(x=>({...x,kind:'accessories'}))];$('gear-list').innerHTML=gear.map((x,i)=>`<article class="inventory-move"><span class="move-order">${x.rarity[0].toUpperCase()}</span><div class="move-info"><b>${x.name}</b><small>${x.kind} · ${x.rarity}</small></div>${x.kind==='weapons'?`<button class="equip-button" data-gear="${i}">${x.equipped?'UNEQUIP':'EQUIP'}</button>`:''}</article>`).join('')||'<div class="inventory-hint">No gear found yet. Raids and story chests can drop equipment.</div>';
 $('technique-slot-label').textContent=state.equippedTechniques.length+' / '+state.techniqueSlots+' active · Takao grants a second slot';$('technique-loadout').innerHTML=state.techniques.map(t=>`<article class="technique-choice"><div><b>${t.name}</b><small>${t.rarity} · level ${t.level} / 1000 · ${(t.moves||TECHNIQUES.find(x=>x.id===t.id)?.moves||[]).length} moves</small></div><button class="secondary" data-tech-toggle="${t.id}">${state.equippedTechniques.includes(t.id)?'UNEQUIP':'EQUIP'}</button></article>`).join('')||'<small class="inventory-hint">Learn techniques from Gacha or the admin panel.</small>';
 $('profile-energy').textContent=`CURSED ENERGY ${state.stats.energy} · Defense ${state.stats.defense} · Melee ${state.stats.melee} · Stat points ${state.statPoints||0}`;$('stat-upgrades').innerHTML=['energy','defense','melee'].map(k=>`<button class="secondary stat-up" data-stat="${k}">+ ${k.toUpperCase()}</button>`).join('');
 if(state.admin){$('admin-lock').classList.add('hidden');$('admin-controls').classList.remove('hidden');}$('admin-fields').innerHTML=`<label>Level <input id="admin-level" type="number" value="${state.level}"></label><label>Yen <input id="admin-yen" type="number" value="${state.yen}"></label><label>Stat points <input id="admin-points" type="number" value="${state.statPoints||0}"></label><label>Skill slots <input id="admin-slots" type="number" value="${state.moveSlots||8}"></label><label>Technique slots <input id="admin-tech-slots" type="number" value="${state.techniqueSlots||1}"></label><label>Trait <select id="admin-trait"><option value="">No trait change</option>${TRAITS.map(t=>`<option value="${t.name}">${t.name} · ${t.rarity}</option>`).join('')}</select></label>`;$('admin-tech').innerHTML='<option value="">No technique change</option>'+TECHNIQUES.map(t=>`<option value="${t.id}">${t.name} · ${t.rarity}</option>`).join('')+[['goku','Goku'],['rimuru','Demon King'],['antispiral','Anti-Spiral'],['zombie-gojo','Zombie Gojo']].map(([id,n])=>`<option value="admin:${id}">${n} · Admin</option>`).join('');
 $('admin-tech-level-fields').innerHTML=`<label>Technique to level <select id="admin-level-technique"><option value="">Select technique</option>${state.techniques.map(t=>`<option value="${t.id}">${t.name} · Lv ${t.level}</option>`).join('')}</select></label><label>Set technique level <input id="admin-tech-level" type="number" min="1" max="1000" placeholder="1–1000"></label>`;$('admin-bosses').innerHTML=bosses.map((b,i)=>`<button class="secondary" data-admin-boss="${i}">FIGHT ${b[0]}</button>`).join('');
}
function chest(source){const rarities=['common','uncommon','rare','epic','legendary','secret'],weights=[48,27,15,7,2.5,.5];let roll=Math.random()*100,r='common';for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<=0){r=rarities[i];break;}}const names=r==='secret'?['Inverted Spear of Heaven','Inventory Curse']:r==='legendary'?['Playful Cloud','Soul Split Katana']:['Cursed Tool','Sorcerer Charm'];const name=source.toLowerCase().includes('toji')?'Inverted Spear of Heaven':names[Math.floor(Math.random()*names.length)],item={name,rarity:name==='Inverted Spear of Heaven'?'secret':r,equipped:true};if(['Inverted Spear of Heaven','Playful Cloud','Soul Split Katana'].includes(name))state.gear.weapons.push(item);else state.gear.accessories.push(item);notify(`${r.toUpperCase()} CHEST · ${name} · ${source}`);}
let raid=null;
function raidPlayerMax(){return 100+state.level*8+state.stats.energy*5;}
function startRaid(kind){const now=Date.now(),cost=kind==='dungeon'?100000:1000000,cd=state.raidCooldowns[kind]||0;if(state.yen<cost){notify('Not enough ¥ for this raid.');return;}if(now<cd){notify('Raid cooldown: '+Math.ceil((cd-now)/60000)+' min remaining.');return;}state.yen-=cost;const max=raidPlayerMax(),power=combatPower();raid={kind,wave:1,target:kind==='dungeon'?25:Infinity,hp:Math.max(12,power*8),maximum:Math.max(12,power*8),playerHp:max,playerMax:max,enemyDamage:.065,blockNext:false};state.raidCooldowns[kind]=now+600000;$('raid-log').textContent='The first curse approaches. Choose your attack.';raidShow();render();}
function startBoss(i){const bosses=[['Gojo Satoru',12,.075],['Ryomen Sukuna',15,.085],['Toji Fushiguro',10,.08],['Mahito',11,.07]],b=bosses[i],power=combatPower(),max=raidPlayerMax();raid={kind:'boss',boss:b[0],wave:1,target:1,hp:Math.max(12,power*b[1]),maximum:Math.max(12,power*b[1]),playerHp:max,playerMax:max,enemyDamage:b[2],blockNext:false};$('raid-log').textContent=b[0]+' steps into the fight. Your move.';raidShow();}
function raidShow(){if(!raid)return;$('raid-status').textContent=raid.kind==='boss'?'CANON BOSS':'WAVE '+raid.wave+' / '+(raid.target===Infinity?'∞':raid.target);$('raid-title').textContent=raid.boss||`${raid.kind==='dungeon'?'Dungeon':'Infinity'} Curse`;$('raid-hp-fill').style.width=Math.max(0,raid.hp/raid.maximum*100)+'%';$('raid-hp-label').textContent=fmt(Math.max(0,raid.hp))+' / '+fmt(raid.maximum)+' HP';$('raid-player-fill').style.width=Math.max(0,raid.playerHp/raid.playerMax*100)+'%';$('raid-player-label').textContent=fmt(Math.max(0,raid.playerHp))+' / '+fmt(raid.playerMax)+' HP';$('raid-attack').disabled=false;$('raid-retreat').disabled=false;}
function raidAttack(){if(!raid)return;const power=combatPower(),damage=Math.max(1,Math.floor(power*(1.45+state.stats.melee*.012)));raid.hp-=damage;if(raid.hp<=0){if(raid.kind==='boss'){chest(raid.boss);state.yen+=10000;raid=null;$('raid-title').textContent='Victory · boss defeated';$('raid-log').textContent='The boss is defeated. You survived the encounter.';$('raid-attack').disabled=true;$('raid-retreat').disabled=true;render();return;}if(raid.wave<raid.target){if(Math.random()<.22)chest('raid wave '+raid.wave);raid.wave++;raid.maximum=Math.max(12,Math.floor(power*(5+raid.wave*1.6)));raid.hp=raid.maximum;raid.playerHp=Math.min(raid.playerMax,raid.playerHp+Math.floor(raid.playerMax*.12));raid.enemyDamage=Math.min(.18,.06+raid.wave*.003);raidShow();$('raid-log').textContent='Wave '+(raid.wave-1)+' cleared. A stronger curse attacks!';render();return;}chest(raid.kind+' raid');state.yen+=raid.kind==='dungeon'?250000:1000000;raid=null;$('raid-title').textContent='Raid complete';$('raid-log').textContent='All waves cleared. You made it out alive.';$('raid-attack').disabled=true;$('raid-retreat').disabled=true;render();return;}
const raw=Math.floor(raid.playerMax*raid.enemyDamage),incoming=Math.max(1,Math.floor(raw*100/(100+state.stats.defense*2))),taken=raid.blockNext?Math.ceil(incoming*.3):incoming;raid.blockNext=false;raid.playerHp-=taken;$('raid-log').textContent='You deal '+fmt(damage)+' damage. '+(raid.boss||'The curse')+' counters for '+fmt(taken)+'.';if(raid.playerHp<=0){const lost=raid.boss||('Wave '+raid.wave);raid=null;$('raid-status').textContent='DEFEATED';$('raid-title').textContent='You were defeated';$('raid-log').textContent=lost+' overcame you. Recover and try again.';$('raid-attack').disabled=true;$('raid-retreat').disabled=true;render();return;}raidShow();save();}
function render(){applySettings();const needed=xpNeed(state.level),d=currentDistrict();syncGradeMoves();$("yen").textContent=fmt(state.yen);$("header-level").textContent=fmt(state.level);$("level-label").textContent=fmt(state.level);$("xp-fill").style.width=Math.min(100,state.xp/needed*100)+"%";$("xp-label").textContent=fmt(state.xp)+" / "+fmt(needed)+" XP";$("welcome-title").textContent=state.level>1?rankName()+" · Level "+state.level:"The veil is waiting.";$("power-home").textContent=fmt(combatPower());$("district-home").textContent=state.settings.language==="ja"?d.ja:d.name;$("wins-home").textContent=fmt(state.wins);$("rebirth-home").textContent=fmt(state.rebirths);$("prestige-home").textContent=fmt(state.prestiges);$("trait-home").textContent=state.trait?state.trait.name:tr("unawakened");$("trait-home").className="rarity "+(state.trait?.rarity||"common");$("tech-home").textContent=state.techniques.length?state.techniques[state.techniques.length-1].name:tr("none");$("tech-home").className="rarity "+(state.techniques.at(-1)?.rarity||"common");$("profile-grade").textContent=rankName()+" "+tr("grade");$("profile-level").textContent=fmt(state.level);$("profile-xp-fill").style.width=Math.min(100,state.xp/needed*100)+"%";$("profile-xp-label").textContent=fmt(state.xp)+" / "+fmt(needed)+" XP";$("profile-wins").textContent=fmt(state.lifetimeWins);$("profile-earned").textContent=fmt(state.lifetimeYen)+" ¥";$("profile-rebirths").textContent=fmt(state.lifetimeRebirths);$("profile-prestiges").textContent=fmt(state.prestiges);$("profile-trait").textContent=state.trait?state.trait.name:tr("unawakened");$("profile-trait").className="rarity "+(state.trait?.rarity||"common");$("trait-bonus").textContent="+"+Math.round((state.trait?.bonus||0)*100)+"% combat power";const equippedTech=state.techniques.at(-1);$("profile-tech").textContent=equippedTech?equippedTech.name:tr("none");$("profile-tech").className="rarity "+(equippedTech?.rarity||"common");$("tech-bonus").textContent=state.techniques.length+" learned techniques";$("rebirth-requirement").textContent=fmt(rebirthNeed());$("rebirth-bonus").textContent="+10% "+tr("damageBonus");$("rebirth-count").textContent="REBIRTHS: "+fmt(state.rebirths);$("rebirth-total").textContent=fmt(state.rebirths);document.querySelector("#view-rebirth .reset-side>p").textContent=fmt(state.rebirths)+" rebirths · +"+Math.round(state.rebirths*10)+"% permanent combat power";$("next-rebirth-text").textContent=state.level>=rebirthNeed()?"Ready to rebirth.":tr("rebirthNeed")+" "+fmt(rebirthNeed())+".";$("rebirth-button").disabled=state.level<rebirthNeed();$("prestige-requirement").textContent=fmt(state.rebirths)+" / 20";$("prestige-count").textContent="PRESTIGES: "+fmt(state.prestiges);$("prestige-total").textContent=fmt(state.prestiges);$("prestige-buff").textContent="+"+Math.round(state.prestiges*25)+"% combat · +"+Math.round(state.prestiges*25)+"% rewards";$("prestige-fill").style.width=Math.min(100,state.rebirths/20*100)+"%";$("prestige-button").disabled=state.rebirths<20;$("prestige-button").title=state.rebirths<20?tr("prestigeNeed"):"";const next=MISSIONS.find(m=>!state.claimed.includes(m.id));$("next-mission-title").textContent=next?next.title:tr("complete");$("next-mission-desc").textContent=next?next.desc:"All current assignments cleared";renderDistricts();renderInventory();renderBattle();renderMissions();renderGacha();renderExtra();if(raid)raidShow();save();}
function weighted(table){const roll=Math.random()*100,rarity=roll<55?"common":roll<82?"uncommon":roll<94?"rare":roll<99?"epic":"legendary",matches=table.filter(x=>x.rarity===rarity);return matches[Math.floor(Math.random()*matches.length)];}
function rollGacha(kind){const price=kind==="technique"?750:500;if(state.yen<price){notify(tr("needYen"));return;}state.yen-=price;if(kind==="style"){state.style=weighted(STYLES);notify("FIGHTING STYLE · "+state.style.name+" ["+state.style.rarity.toUpperCase()+"]");}else if(kind==="trait"){state.trait=weighted(TRAITS);state.techniqueSlots=state.trait.name==="Takao"?2:1;if(state.trait.name==="Heavenly Restriction")state.gear.accessories.push({name:"Inventory Curse",rarity:"rare",equipped:true});notify("TRAIT · "+state.trait.name+" ["+state.trait.rarity.toUpperCase()+"]");}else{const chosen=weighted(TECHNIQUES),existing=state.techniques.find(t=>t.id===chosen.id);if(existing){existing.xp+=100;while(existing.xp>=existing.level*100){existing.xp-=existing.level*100;existing.level++;}notify("DUPLICATE · "+existing.name+" is now Lv. "+existing.level);}else{const tech=Object.assign({},chosen,{level:1,xp:0});state.techniques.push(tech);const id="tech-"+tech.id;if(state.moveOrder.length<(state.moveSlots||8)&&state.equippedTechniques.length<state.techniqueSlots){state.equippedTechniques.push(tech.id);const first=tech.moves[0];if(first)state.moveOrder.push("tech-"+tech.id+"-"+first.id);}notify("TECHNIQUE LEARNED · "+tech.name);}}render();}
function moveById(id){return moveCatalog().find(m=>m.id===id);}
function startBattle(){if(battle)return;const d=currentDistrict();enemyMax=Math.floor((28+state.level*5+state.wins*.8)*Math.sqrt(d.factor));enemyHp=enemyMax;playerMax=100+state.level*8;playerHp=playerMax;blockNext=false;battle={playerTurn:true};$("battle-log").textContent=d.enemy+" appears. Your turn.";renderBattle();}
function techniqueUse(move){if(!move.technique||move.technique.level>=1000)return;move.technique.xp+=30;while(move.technique.xp>=move.technique.level*100&&move.technique.level<1000){move.technique.xp-=move.technique.level*100;move.technique.level++;notify(move.technique.name+" reached Lv. "+move.technique.level);}}
function finishBattle(won){battle=null;const d=currentDistrict();if(won){state.wins++;state.lifetimeWins++;addXp(d.xp);addYen(d.yen);$("battle-log").textContent="Exorcism complete. +"+d.xp+" XP · +"+Math.floor(d.yen*prestigeBoost())+" ¥. Start another battle when ready.";}else{$("battle-log").textContent="You were overwhelmed. Start again when ready.";}render();}
function playerAction(id){if(!battle||!battle.playerTurn)return;const move=moveById(id);if(!move)return;if(move.type==="flee"){battle=null;enemyHp=0;$("battle-log").textContent="You fled. No rewards earned.";renderBattle();return;}let message="";if(move.type==="attack"||move.type==="energy"){const energy=move.type==="energy",chance=Math.min(.75,(energy?.08:.02)+(state.trait?.blackFlash||0)+(state.style?.name==="Black Flash Specialist"?.08:0)),black=Math.random()<chance,damage=Math.floor(combatPower()*(energy?2.5:1.8)*(black?2.4:1));enemyHp-=damage;message=black?"BLACK FLASH! "+move.name+" deals "+damage+" damage!":move.name+" hits for "+damage+" damage.";}else if(move.type==="block"){blockNext=true;message="You brace for the curse's attack.";}else if(move.type==="heal"){const amount=move.id==="basic-rct"?Math.floor(playerMax*.2):move.id==="normal-rct"?Math.floor(playerMax*.36):Math.floor(playerMax*.55);const healed=Math.min(amount,playerMax-playerHp);playerHp+=healed;message=move.name+" restores "+healed+" HP.";}else if(move.type==="weapon"){const damage=Math.floor(combatPower()*1.7);enemyHp-=damage;message=move.name+' deals '+damage+' damage.';}else if(move.type==="technique"){const damage=Math.floor(combatPower()*(move.damage||move.technique.damage)*(1+(move.technique.level-1)*.12));enemyHp-=damage;techniqueUse(move);message=move.name+" deals "+damage+" damage (Lv. "+move.technique.level+").";}$("battle-log").textContent=message;if(enemyHp<=0){finishBattle(true);return;}const incoming=Math.max(3,Math.floor(4+state.level*.3+Math.sqrt(currentDistrict().factor)*4));const taken=blockNext?Math.ceil(incoming*.2):incoming;playerHp-=taken;blockNext=false;message+=" Curse counterattacks for "+taken+" damage.";$("battle-log").textContent=message;if(playerHp<=0){finishBattle(false);return;}battle.playerTurn=true;renderBattle();save();}
function renderOnlineActions(){const holder=$("online-actions");if(!arenaMatch){holder.innerHTML="";return;}holder.innerHTML=moveCatalog().filter(m=>state.moveOrder.includes(m.id)).map(m=>'<button class="action-button" data-online-action="'+m.id+'" '+(!arenaMatch.yourTurn?"disabled":"")+'><b>'+m.name+'</b><small>'+m.desc+'</small></button>').join("");}
async function connectArena(){if(arenaSocket)return true;try{if(typeof WebsimSocket==="undefined")throw new Error("Realtime arena is unavailable in this preview.");arenaSocket=await WebsimSocket.joinRoom();arenaSocket.onmessage=event=>{let msg;try{msg=JSON.parse(event.data);}catch{return;}handleArenaMessage(msg);};arenaSocket.onclose=event=>{arenaSocket=null;arenaMatch=null;arenaQueued=false;$("online-status").querySelector("span").textContent=event.reason||"Disconnected from arena";$("queue-online").classList.remove("hidden");$("leave-online").classList.add("hidden");$("duel-board").classList.add("hidden");};return true;}catch(error){$("online-status").querySelector("span").textContent=error.message||"Could not connect.";return false;}}
async function queueOnline(){const ok=await connectArena();if(!ok)return;arenaSocket.send({type:"queue",moves:state.moveOrder});arenaQueued=true;$("online-status").querySelector("span").textContent="Looking for an opponent…";$("queue-online").classList.add("hidden");$("leave-online").classList.remove("hidden");}
function handleArenaMessage(msg){if(msg.type==="ready"){$("online-status").querySelector("span").textContent="Arena connected. Queue for a duel.";}else if(msg.type==="queued"){$("online-status").querySelector("span").textContent="Looking for an opponent…";}else if(msg.type==="matched"){arenaQueued=false;arenaMatch={id:msg.matchId,youId:msg.you.id,youHp:msg.you.hp,oppHp:msg.opponent.hp,oppName:msg.opponent.username,yourTurn:msg.yourTurn};$("duel-you-name").textContent=msg.you.username||"Sorcerer";$("duel-opponent").textContent=msg.opponent.username||"Opponent";$("online-status").querySelector("span").textContent=msg.yourTurn?"Duel found · your turn":"Duel found · opponent's turn";$("duel-board").classList.remove("hidden");$("queue-online").classList.add("hidden");$("leave-online").classList.remove("hidden");$("online-log").textContent="The duel begins.";renderOnlineActions();updateDuelHealth();}else if(msg.type==="state"&&arenaMatch){arenaMatch.youHp=msg.youHp;arenaMatch.oppHp=msg.opponentHp;arenaMatch.yourTurn=msg.yourTurn;$("online-status").querySelector("span").textContent=msg.yourTurn?"Your turn":"Opponent's turn";$("online-log").textContent=msg.log||"";updateDuelHealth();renderOnlineActions();}else if(msg.type==="finished"){arenaMatch=null;$("online-status").querySelector("span").textContent=msg.won?"You won the duel.":"Duel ended.";$("online-log").textContent=msg.reason||"Match complete.";$("queue-online").classList.remove("hidden");$("leave-online").classList.add("hidden");$("duel-board").classList.add("hidden");$("online-actions").innerHTML="";}else if(msg.type==="left-queue"){arenaQueued=false;$("online-status").querySelector("span").textContent="Left matchmaking queue.";$("queue-online").classList.remove("hidden");$("leave-online").classList.add("hidden");}}
function updateDuelHealth(){$("duel-you-hp").style.width=Math.max(0,arenaMatch.youHp)+"%";$("duel-opponent-hp").style.width=Math.max(0,arenaMatch.oppHp)+"%";$("duel-you-hp-label").textContent=arenaMatch.youHp+" / 100";$("duel-opponent-hp-label").textContent=arenaMatch.oppHp+" / 100";}
function sendOnlineAction(move){if(!arenaSocket||!arenaMatch||!arenaMatch.yourTurn)return;arenaSocket.send({type:"action",matchId:arenaMatch.id,move:move});}
function leaveOnline(){if(arenaSocket){arenaSocket.send({type:"leave"});arenaMatch=null;arenaQueued=false;$("duel-board").classList.add("hidden");$("online-actions").innerHTML="";$("queue-online").classList.remove("hidden");$("leave-online").classList.add("hidden");}}
function renderOnlineAvailability(){if(arenaQueued||arenaMatch)return;fetch("/api/arena").then(r=>r.json()).then(data=>{if(data.available&&!arenaQueued&&!arenaMatch)$("online-status").querySelector("span").textContent="Online arena is available.";}).catch(()=>{});}
function renderSettings(){document.documentElement.style.setProperty("--bg",state.settings.color||"#0d0c12");}
function rebirth(){if(state.level<rebirthNeed()||!confirm(tr("rebirthConfirm")))return;const keep={rebirths:state.rebirths+1,lifetimeRebirths:state.lifetimeRebirths+1,lifetimeWins:state.lifetimeWins,lifetimeYen:state.lifetimeYen,prestiges:state.prestiges,trait:state.trait,style:state.style,techniques:state.techniques,moveOrder:state.moveOrder,settings:state.settings};state=Object.assign(fresh(),keep);battle=null;render();notify("REBIRTH "+state.rebirths+" · +10% PERMANENT POWER");}
function prestige(){if(state.rebirths<20||!confirm(tr("prestigeConfirm")))return;const keep={prestiges:state.prestiges+1,lifetimeWins:state.lifetimeWins,lifetimeYen:state.lifetimeYen,lifetimeRebirths:state.lifetimeRebirths,settings:state.settings};state=Object.assign(fresh(),keep);battle=null;render();notify("PRESTIGE "+state.prestiges+" · +25% PERMANENT POWER");}
function switchTab(name){document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.tab===name));document.querySelectorAll(".view").forEach(v=>v.classList.toggle("active",v.id==="view-"+name));const tab=document.querySelector('.tab[data-tab="'+name+'"]');$("page-heading").textContent=tab?tr(tab.dataset.t).toLocaleUpperCase(state.settings.language==="ja"?"ja-JP":"en-US"):name.toUpperCase();if(name==="battle")renderOnlineAvailability();}
function setMode(mode){activeBattleMode=mode;document.querySelectorAll(".mode-tab").forEach(b=>b.classList.toggle("active",b.dataset.mode===mode));$("pve-mode").classList.toggle("hidden",mode!=="pve");$("online-mode").classList.toggle("hidden",mode!=="online");if(mode==="online")renderOnlineAvailability();}
document.querySelector(".tabs").addEventListener("click",e=>{const b=e.target.closest("[data-tab]");if(b)switchTab(b.dataset.tab);});document.addEventListener("click",e=>{const b=e.target.closest("[data-go]");if(b)switchTab(b.dataset.go);});
$("district-list").addEventListener("click",e=>{const b=e.target.closest("[data-district]");if(!b)return;const d=DISTRICTS.find(x=>x.id===b.dataset.district);if(!d||state.level<d.level)return;state.district=d.id;battle=null;render();});
$('technique-loadout').addEventListener('click',e=>{const b=e.target.closest('[data-tech-toggle]');if(!b)return;const id=b.dataset.techToggle,index=state.equippedTechniques.indexOf(id);if(index>=0){state.equippedTechniques.splice(index,1);state.moveOrder=state.moveOrder.filter(m=>!m.startsWith('tech-'+id+'-'));}else if(state.equippedTechniques.length>=state.techniqueSlots){notify('Technique slots are full. Gain Takao or add slots in admin.');return;}else{state.equippedTechniques.push(id);const t=state.techniques.find(x=>x.id===id),first=(t?.moves||TECHNIQUES.find(x=>x.id===id)?.moves||[])[0];if(first&&state.moveOrder.length<(state.moveSlots||8))state.moveOrder.push('tech-'+id+'-'+first.id);}render();});
$("inventory-list").addEventListener("click",e=>{const equip=e.target.closest("[data-equip]"),order=e.target.closest("[data-order]");if(equip){const id=equip.dataset.equip,index=state.moveOrder.indexOf(id);if(index>=0)state.moveOrder.splice(index,1);else if(state.moveOrder.length<(state.moveSlots||8))state.moveOrder.push(id);else notify("Your move loadout is full.");render();return;}if(order){const i=state.moveOrder.indexOf(order.dataset.id),j=order.dataset.order==="up"?i-1:i+1;if(i>=0&&j>=0&&j<state.moveOrder.length){[state.moveOrder[i],state.moveOrder[j]]=[state.moveOrder[j],state.moveOrder[i]];render();}}});
$("mission-list").addEventListener("click",e=>{const b=e.target.closest("[data-claim]");if(!b)return;const m=MISSIONS.find(x=>x.id===b.dataset.claim);if(!m||missionValue(m)<m.goal)return;state.claimed.push(m.id);addXp(m.xp);addYen(m.yen);if(Math.random()<.25)chest('mission reward');notify("+"+fmt(m.xp)+" XP · +"+fmt(Math.floor(m.yen*prestigeBoost()))+" ¥");render();});
$("start-battle").addEventListener("click",startBattle);$("battle-actions").addEventListener("click",e=>{const b=e.target.closest("[data-action]");if(b)playerAction(b.dataset.action);});$("roll-style").addEventListener("click",()=>rollGacha("style"));$("roll-technique").addEventListener("click",()=>rollGacha("technique"));$("roll-trait").addEventListener("click",()=>rollGacha("trait"));$("rebirth-button").addEventListener("click",rebirth);$("prestige-button").addEventListener("click",prestige);
$("language-setting").addEventListener("change",e=>{state.settings.language=e.target.value;render();});$("color-setting").addEventListener("input",e=>{state.settings.color=e.target.value;renderSettings();save();});$("reset-save").addEventListener("click",()=>{if(!confirm(tr("resetConfirm")))return;state=fresh();battle=null;render();notify(tr("savedToast"));});
document.querySelectorAll(".mode-tab").forEach(b=>b.addEventListener("click",()=>setMode(b.dataset.mode)));$("queue-online").addEventListener("click",queueOnline);$("leave-online").addEventListener("click",leaveOnline);$("online-actions").addEventListener("click",e=>{const b=e.target.closest("[data-online-action]");if(b)sendOnlineAction(b.dataset.onlineAction);});
document.querySelectorAll('.raid-start').forEach(b=>b.addEventListener('click',()=>startRaid(b.dataset.raid)));
$('raid-attack').addEventListener('click',raidAttack);$('raid-retreat').addEventListener('click',()=>{raid=null;$('raid-status').textContent='RAID RETREATED';$('raid-attack').disabled=true;$('raid-retreat').disabled=true;});
$('boss-list').addEventListener('click',e=>{const b=e.target.closest('[data-boss]');if(b)startBoss(+b.dataset.boss);});
$('story-list').addEventListener('click',e=>{const b=e.target.closest('[data-story]');if(!b)return;const n=+b.dataset.story;if(n!==state.story)return;state.story++;state.yen+=5000;state.xp+=250;if(Math.random()<.65)chest('story chapter');render();notify('Chapter complete · ¥5,000');});
$('awakening-list').addEventListener('click',e=>{const b=e.target.closest('[data-awaken]'),t=state.techniques.find(x=>x.id===b?.dataset.awaken);if(t&&t.level>=1000&&!t.awakened){t.awakened=true;t.damage*=1.5;render();notify(t.name+' awakened');}});
document.querySelectorAll('.inv-tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.inv-tab').forEach(x=>x.classList.toggle('active',x===b));const skills=b.dataset.inv==='skills';$('inventory-list').classList.toggle('hidden',!skills);$('gear-list').classList.toggle('hidden',skills);$('move-count').classList.toggle('hidden',!skills);$('inv-heading').textContent=b.dataset.inv.toUpperCase();}));
$('gear-list').addEventListener('click',e=>{const b=e.target.closest('[data-gear]');if(!b)return;const all=[...state.gear.weapons,...state.gear.accessories],item=all[+b.dataset.gear];if(item){item.equipped=!item.equipped;render();}});
$('stat-upgrades').addEventListener('click',e=>{const b=e.target.closest('[data-stat]');if(!b)return;if((state.statPoints||0)<1){notify('No stat points available.');return;}state.statPoints--;state.stats[b.dataset.stat]++;render();});
$('dummy-hit').addEventListener('click',()=>{$('dummy-result').textContent='Basic punch damage: '+Math.floor(combatPower()*1.8)+' · Cursed energy punch: '+Math.floor(combatPower()*2.5)+' · Techniques: '+state.techniques.map(t=>t.name+' '+Math.floor(combatPower()*t.damage*(1+(t.level-1)*.12))).join(' / ');});
$('admin-trigger').addEventListener('click',()=>{if(!state.admin){$('admin-panel').classList.remove('hidden');return;}$('admin-panel').classList.toggle('hidden');});
$('admin-unlock').addEventListener('click',()=>{if($('admin-code').value!=='265307'){notify('Access code rejected.');return;}state.admin=true;save();$('admin-lock').classList.add('hidden');$('admin-controls').classList.remove('hidden');renderExtra();});
$('admin-apply').addEventListener('click',()=>{state.level=Math.max(1,+$('admin-level').value||1);state.yen=Math.max(0,+$('admin-yen').value||0);state.statPoints=Math.max(0,+$('admin-points').value||0);state.moveSlots=Math.max(1,+$('admin-slots').value||8);state.techniqueSlots=Math.max(1,Math.floor(+$('admin-tech-slots').value||1));const levelTarget=state.techniques.find(t=>t.id===$('admin-level-technique').value),setLevel=+$('admin-tech-level').value;if(levelTarget&&setLevel>=1){levelTarget.level=Math.min(1000,Math.floor(setLevel));levelTarget.xp=0;}const trait=$('admin-trait').value;if(trait){state.trait=TRAITS.find(t=>t.name===trait)||null;if(trait==='Takao')state.techniqueSlots=Math.max(2,state.techniqueSlots);if(trait==='Heavenly Restriction'&&!state.gear.accessories.some(a=>a.name==='Inventory Curse'))state.gear.accessories.push({name:'Inventory Curse',rarity:'rare',equipped:true});}const selection=$('admin-tech').value;if(selection){let tech;if(selection.startsWith('admin:')){const id=selection.slice(6),info={goku:['Goku Technique',5],rimuru:['Demon King Technique',6],antispiral:['Anti-Spiral Technique',8],'zombie-gojo':['Zombie Gojo Technique',4]}[id];tech={id,name:info[0],rarity:'legendary',damage:info[1],level:1,xp:0,admin:true,moves:[{id:'strike',name:info[0]+' · Strike',damage:info[1],desc:'Technique strike.'},{id:'surge',name:info[0]+' · Surge',damage:info[1]*1.4,desc:'Charged technique.'},{id:'finisher',name:info[0]+' · Finisher',damage:info[1]*1.8,desc:'Technique finisher.'}]};}else tech={...TECHNIQUES.find(t=>t.id===selection),level:1,xp:0};let owned=state.techniques.find(t=>t.id===tech.id);if(!owned){state.techniques.push(tech);owned=tech;}if(!state.equippedTechniques.includes(tech.id)&&state.equippedTechniques.length<state.techniqueSlots){state.equippedTechniques.push(tech.id);const first=(owned.moves||TECHNIQUES.find(t=>t.id===tech.id)?.moves||[])[0];if(first&&state.moveOrder.length<(state.moveSlots||8))state.moveOrder.push('tech-'+tech.id+'-'+first.id);}}render();notify('Admin changes applied.');});
$('admin-bosses').addEventListener('click',e=>{const b=e.target.closest('[data-admin-boss]');if(b){startBoss(+b.dataset.adminBoss);switchTab('raids');}});
render();
